def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Determine our urgency
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Alive opponents
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        # If alone, bid enough to secure water for remaining needs
        cap = min(budget, DAILY_SALARY * 0.6)
        return max(0.0, cap)

    # Read yesterday bids to infer who is pressuring
    prev_bids = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Identify Eric-like collapse signal: if someone had very low bid and died, reduce our overbidding
    # (We only have yesterday trace; use it to detect low-bid behavior among alive too.)
    low_bidters = 0
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                if float(prev['bid']) <= DAILY_SALARY * 0.2:
                    low_bidters += 1
            except Exception:
                pass

    # Supply pressure: higher supply reduces need to overbid
    # Normalize supply into [0,1]
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        supply_ratio = 0.5
    else:
        supply_ratio = (supply - MIN_SUPPLY) / denom
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Base bid level: mid-tier to compete with likely survivors
    base = DAILY_SALARY * (0.45 + 0.15 * supply_ratio)  # ~31.5 to 52.5

    # If our hp is critical or we've gone multiple no-water days, we must secure water
    critical = (hp <= 2.0) or (no_water_days >= 2)

    # If yesterday someone bid extremely high, we avoid getting into a bidding war unless critical
    very_high = highest_prev_bid >= DAILY_SALARY * 0.85

    # Decide target bid
    if critical:
        # Bid aggressively but not maxing out: try to beat yesterday's top by a small margin
        target = max(base, highest_prev_bid + 2.0)
        # If top was already huge, still cap to avoid bankruptcy
        target = min(target, DAILY_SALARY * 0.95)
    else:
        if very_high:
            # Don't chase; let others pay. Bid around base or slightly above second-highest.
            target = max(base, second_prev_bid + 1.0)
        else:
            # If no one was pressuring, bid slightly above base; if low bidters exist, can lower a bit.
            if low_bidters >= 1:
                target = base * 0.95
            else:
                target = base * 1.05

    # Convert to feasible bid within our budget
    if budget <= 0.0:
        return 0.0

    # Ensure non-negative
    bid = max(0.0, min(float(budget), float(target)))

    # Slightly adjust by day parity to avoid predictability
    if int(day) % 2 == 0:
        bid *= 1.02
    else:
        bid *= 0.98

    # Final clamp
    bid = max(0.0, min(float(budget), bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp_bids = []
    reqs = [WATER_REQ]

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_opp_bids.append(float(bid))

    total_players = 1 + len(alive)
    total_req = sum(reqs)

    scarcity = total_req / max(supply, 1.0)
    per_capita = supply / max(total_players, 1)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else highest_prev

    my_urgent = hp <= 3 or no_water_days >= 1
    extreme_urgent = hp <= 2 or no_water_days >= 2

    if not alive:
        base = 18.0 if not my_urgent else 45.0
        if supply <= 17:
            base += 8.0
        return max(0.0, min(float(budget), base))

    if extreme_urgent:
        target = max(88.0, urgent_prev + 6.0, highest_prev + 4.0)
        if supply <= 17:
            target += 8.0
        return max(0.0, min(float(budget), target))

    if my_urgent:
        target = max(62.0, highest_prev + 3.0)
        if scarcity > 1.8:
            target += 10.0
        elif scarcity > 1.4:
            target += 5.0
        if supply <= 17:
            target += 6.0
        return max(0.0, min(float(budget), target))

    if scarcity >= 2.0 or per_capita < WATER_REQ * 0.55:
        target = max(58.0, second_prev + 2.0)
    elif scarcity >= 1.6 or per_capita < WATER_REQ * 0.75:
        target = max(44.0, highest_prev * 0.72)
    else:
        target = max(24.0, highest_prev * 0.45)

    if highest_prev >= 120.0:
        target = min(target, 52.0)
    elif highest_prev >= 90.0:
        target = min(target, 56.0)

    if day >= 8 and budget > DAILY_SALARY * 3:
        target += 4.0

    if supply >= 23 and hp >= 6:
        target -= 4.0

    target = max(12.0, target)
    return max(0.0, min(float(budget), float(target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if my_status['hp'] <= 2:
            bid_amount = highest_prev_bid + (DAILY_SALARY * 0.1)
            bid = min(my_status['budget'], bid_amount, DAILY_SALARY * 0.95)
        elif my_status['hp'] <= 4:
            bid_amount = highest_prev_bid + (DAILY_SALARY * 0.05)
            bid = min(my_status['budget'], bid_amount, DAILY_SALARY * 0.8)
        else:
            if highest_prev_bid >= DAILY_SALARY * 0.8:
                bid = min(my_status['budget'], DAILY_SALARY * 0.6)
            else:
                bid = min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.0))
    else:
        if my_status['hp'] <= 2:
            bid = min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            bid = min(my_status['budget'], DAILY_SALARY * 0.6)

    bid = min(bid, my_status['budget'])
    bid = min(bid, float(DAILY_SALARY))
    bid = max(1.0, bid)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 3:
            bid = min(my_status['budget'], float(DAILY_SALARY))
        elif my_status['hp'] > 3 and remaining_days == 1:
            bid = min(my_status['budget'], DAILY_SALARY * 0.75)
        elif my_status['hp'] > 3 and remaining_days == 0:
            bid = min(my_status['budget'], DAILY_SALARY * 0.5)

    return float(bid)

